sys_script_fix.script:
// ======================================================================
// CMDB Upstream Relation Completeness Check (with Relation Types + Debug)
// Author: Rolf + Copilot
// ======================================================================

// ----------------------------------------------------------------------
// DEFINE EXPECTED UPSTREAMS PER RELATION TYPE
// ----------------------------------------------------------------------

var REQUIRED = {
    "Runs on": [
        "cmdb_ci_hardware",
        "cmdb_ci_esx_server"
    ],
    "Depends on": [
        "cmdb_ci_database",
        "cmdb_ci_app_server"
    ],
    "Hosted on": [
        "cmdb_ci_ip_switch",
        "cmdb_ci_ip_router",
        "cmdb_ci_lb"
    ]
};

// ----------------------------------------------------------------------
// MAIN EXECUTION
// ----------------------------------------------------------------------

gs.info("=== CMDB Upstream Relation Check START ===");

var results = [];

var serverGR = new GlideRecord('cmdb_ci_server');
serverGR.query();

while (serverGR.next()) {

    var serverSysId = serverGR.getUniqueValue();
    var serverName = serverGR.getValue('name');

    gs.info("Checking server: " + serverName + " (" + serverSysId + ")");

    var serverResult = {
        server: serverName,
        sys_id: serverSysId,
        relation_types: {}
    };

    // Loop through each relation type definition
    for (var relType in REQUIRED) {

        gs.info("  Relation type: " + relType);

        var expectedClasses = REQUIRED[relType];
        var present = [];
        var missing = [];

        for (var i = 0; i < expectedClasses.length; i++) {
            var upstreamClass = expectedClasses[i];

            gs.info("    Checking upstream class: " + upstreamClass);

            var relGR = new GlideRecord('cmdb_rel_ci');
            relGR.addQuery('child', serverSysId);
            relGR.addQuery('type.name', relType);
            relGR.addQuery('parent.sys_class_name', upstreamClass);
            relGR.query();

            if (relGR.hasNext()) {
                gs.info("      ✔ FOUND relation to " + upstreamClass);
                present.push(upstreamClass);
            } else {
                gs.info("      ✘ MISSING relation to " + upstreamClass);
                missing.push(upstreamClass);
            }
        }

        serverResult.relation_types[relType] = {
            present_upstreams: present,
            missing_upstreams: missing
        };
    }

    results.push(serverResult);
}

gs.info("=== CMDB Upstream Relation Check DONE ===");

// Output JSON summary
gs.info("=== RESULT JSON START ===");
gs.info(JSON.stringify(results, null, 2));
gs.info("=== RESULT JSON END ===");
